(7638433, 1239787, 3306, '<td valign="top">I love the depth and simplicity of your composition. Definitely a contender.</td>', 'I love the depth and simplicity of your composition. Definitely a contender.', '2019-08-18 18:52:51.000000', NULL, 1),
(7638434, 1239738, 3306, '<td valign="top">The lighting on the subject is outstanding. An absolutely beautiful portrait.</td>', 'The lighting on the subject is outstanding. An absolutely beautiful portrait.', '2019-08-18 18:53:53.000000', NULL, 1),
